/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void hobp_err_add (Hobp_Error_Code code)
{  
  UInt8 ptr = hobp_vars.err.count %HOBP_ERR_BUFF_SIZE ;
 
  hobp_vars.err.code[ptr] = code ;

  hobp_vars.err.count++ ;

  ATOMIC(hobp_vars.do_err_save = TRUE) ;
}

//--------------------------------------------------------------------------//
Boolean hobp_err_save (void)           
{ 
  if(hobp_vars.do_err_save == TRUE)
    {
      if(nvfs_wr(nvfs_hobp_error, &hobp_vars.err) != NVFS_OK)
        {
          return FALSE ;
        }
      ATOMIC(hobp_vars.do_err_save = FALSE) ;

      #if DBG_HOBP == 1
        hobp_dbg_print("\nErr Save" , NULL , NULL) ;
      #endif
    }
  return TRUE ;
}
//--------------------------------------------------------------------------//

Boolean hobp_err_detect(void)
{
  static UInt8 last_count = NULL ;

  if(last_count != hobp_vars.err.count)
    {
      ATOMIC(last_count = hobp_vars.err.count);

      return TRUE ;
    }
  
  return FALSE ;
}

